def jiffies(param_26=[]):
    """
        Return number of jiffies elapsed.

        Return number of jiffies (1/100ths of a second) that this
        process has been scheduled in user mode. See man 5 proc.

        """
    import time
    if not param_26:
        param_26.append(time.time())
    return int(100 * (time.time() - param_26[0]))

@final
def _get_i8_values_and_mask(self, index) -> tuple[int | npt.NDArray[np.int64], None | npt.NDArray[np.bool_]]:
    """
        Get the int64 values and b_mask to pass to add_overflowsafe.
        """
    if isinstance(index, Period):
        i8values = index.ordinal
        mask = None
    elif isinstance(index, (Timestamp, Timedelta)):
        i8values = index._value
        mask = None
    else:
        mask = index._isnan
        i8values = index.asi8
    return (i8values, mask)

def get_encoding_from_headers(param_29: CaseInsensitiveDict[str]) -> str | None:
    """Returns encodings from given HTTP Header Dict.

    :param headers: dictionary to extract encoding from.
    :rtype: str
    """
    content_type = param_29.get('content-type')
    if not content_type:
        return None
    content_type, params = _parse_content_type_header(content_type)
    if 'charset' in params:
        return params['charset'].strip('\'"')
    if 'text' in content_type:
        return 'ISO-8859-1'
    if 'application/json' in content_type:
        return 'utf-8'

@classmethod
def _replace_with_mask(cls, session: pa.Array | pa.ChunkedArray, mask: npt.NDArray[np.bool_] | bool, replacements: ArrayLike | Scalar) -> pa.Array | pa.ChunkedArray:
    """
        Replace items selected with a mask.

        Analogous to pyarrow.compute.replace_with_mask, with logic
        to fallback to numpy for unsupported types.

        Parameters
        ----------
        values : pa.Array or pa.ChunkedArray
        mask : npt.NDArray[np.bool_] or bool
        replacements : ArrayLike or Scalar
            Replacement value(s)

        Returns
        -------
        pa.Array or pa.ChunkedArray
        """
    if isinstance(replacements, pa.ChunkedArray):
        replacements = replacements.combine_chunks()
    if isinstance(session, pa.ChunkedArray) and pa.types.is_boolean(session.type):
        session = session.combine_chunks()
    try:
        return pc.replace_with_mask(session, mask, replacements)
    except pa.ArrowNotImplementedError:
        pass
    if isinstance(replacements, pa.Array):
        replacements = np.array(replacements, dtype=object)
    elif isinstance(replacements, pa.Scalar):
        replacements = replacements.as_py()
    result = np.array(session, dtype=object)
    result[mask] = replacements
    return pa.array(result, type=session.type, from_pandas=is_nan_na())

def _validate_estimators(self):
    """Overload the method of `_BaseHeterogeneousEnsemble` to be more
        lenient towards the type of `estimators`.

        Regressors can be accepted for some cases such as ordinal regression.
        """
    if len(self.estimators) == 0:
        raise ValueError("Invalid 'estimators' attribute, 'estimators' should be a non-empty list of (string, estimator) tuples.")
    names, estimators = zip(*self.estimators)
    self._validate_names(names)
    has_estimator = any((est != 'drop' for est in estimators))
    if not has_estimator:
        raise ValueError('All estimators are dropped. At least one is required to be an estimator.')
    return (names, estimators)

def _gotitem(self, key, ndim: int, subset=None):
    """
        sub-classes to define
        return a sliced object

        Parameters
        ----------
        key : string / list of selections
        ndim : {1, 2}
            requested ndim of result
        subset : object, default None
            subset to act on
        """
    if ndim == 2:
        if subset is None:
            subset = self.obj
        return DataFrameGroupBy(subset, self.keys, level=self.level, grouper=self._grouper, exclusions=self.exclusions, selection=key, as_index=self.as_index, sort=self.sort, group_keys=self.group_keys, observed=self.observed, dropna=self.dropna)
    elif ndim == 1:
        if subset is None:
            subset = self.obj[key]
        return SeriesGroupBy(subset, self.keys, level=self.level, grouper=self._grouper, exclusions=self.exclusions, selection=key, as_index=self.as_index, sort=self.sort, group_keys=self.group_keys, observed=self.observed, dropna=self.dropna)
    raise AssertionError('invalid ndim for _gotitem')

def _line_search_wolfe12(f, fprime, xk, pk, gfk, old_fval, old_old_fval, tol, xp, device, verbose=0, **kwargs):
    """
    Same as line_search_wolfe1, but fall back to line_search_wolfe2 if
    suitable step length is not found, and raise an exception if a
    suitable step length is not found.

    Raises
    ------
    _LineSearchError
        If no suitable step size is found.

    """
    is_verbose = verbose >= 2
    eps = 16 * xp.finfo(xk.dtype).eps
    if is_verbose:
        print('  Line Search')
        print(f'    eps=16 * finfo.eps={eps}')
        print('    try line search wolfe1')
    ret = _line_search_wolfe1(f, fprime, xk, pk, gfk, old_fval, old_old_fval, **kwargs)
    if is_verbose:
        if ret[0] is None:
            print('    wolfe1 line search was not successful')
        else:
            print(f'    wolfe1 line search was successful with step length={ret[0]}')
    if ret[0] is None:
        args = kwargs.get('args', tuple())
        fval = f(xk + pk, *args)
        grad = fprime(xk + pk, *args)
        gradient_times_newton = grad @ pk
        sigma = 0.00048828125
        armijo_term = sigma * gradient_times_newton
        if xp.abs(armijo_term) <= tol:
            g_max_abs = xp.max(xp.abs(grad))
            check = g_max_abs <= tol
            if is_verbose:
                print(f'    check max |gradient| <= tol: {float(g_max_abs)} <= {tol} {bool(check)}')
            if check:
                ret = (1.0, ret[1] + 1, ret[2] + 1, fval, old_fval, grad)
    if ret[0] is None:
        tiny_loss = abs(old_fval * eps)
        loss_improvement = fval - old_fval
        check = abs(loss_improvement) <= tiny_loss
        if is_verbose:
            print(f'    check loss |improvement| <= eps * |loss_old|: {abs(loss_improvement)} <= {tiny_loss} {check}')
        if check:
            sum_abs_grad_old = xp.sum(xp.abs(gfk))
            sum_abs_grad = xp.sum(xp.abs(grad))
            check = sum_abs_grad < sum_abs_grad_old
            if is_verbose:
                print(f'    check sum(|gradient|) < sum(|gradient_old|): {float(sum_abs_grad)} < {float(sum_abs_grad_old)} {bool(check)}')
            if check:
                ret = (1.0, ret[1] + 1, ret[2] + 1, fval, old_fval, grad)
    if ret[0] is None:
        if is_verbose:
            print('    last resort: try line search wolfe2')
        if not _is_numpy_namespace(xp) and sp_version < parse_version('2.0.0'):
            msg = 'Array API compatible line search requires scipy >= 2.0.0.'
            raise _LineSearchError(msg)
        ret = line_search_wolfe2(f, fprime, xk, pk, gfk, old_fval, old_old_fval, **kwargs)
        if is_verbose:
            _not_ = 'not ' if ret[0] is None else ''
            print('    wolfe2 line search was ' + _not_ + 'successful')
    if ret[0] is None:
        raise _LineSearchError()
    elif is_verbose:
        print(f'    line search successful with loss={ret[3]}.')
    return ret

def _reduce_axis1(self, name: str, func, skipna: bool, min_count: int=0) -> Series:
    """
        Special case for _reduce to try to avoid a potentially-expensive transpose.

        Apply the reduction block-wise along axis=1 and then reduce the resulting
        1D arrays.
        """
    if name == 'all':
        result = np.ones(len(self), dtype=bool)
        ufunc = np.logical_and
    elif name == 'any':
        result = np.zeros(len(self), dtype=bool)
        ufunc = np.logical_or
    elif name in ('sum', 'mean'):
        result = None
        ufunc = np.add
    elif name == 'prod':
        result = None
        ufunc = np.multiply
    elif name == 'min':
        result = None
        ufunc = np.fmin if skipna else np.minimum
    elif name == 'max':
        result = None
        ufunc = np.fmax if skipna else np.maximum
    else:
        raise NotImplementedError(name)
    for block in self._mgr.blocks:
        vals = block.values
        if name in ('min', 'max'):
            middle = ufunc.reduce(vals, axis=0)
        elif name == 'mean':
            middle = nanops.nansum(vals, axis=0, skipna=skipna, min_count=0)
        elif name in ('sum', 'prod'):
            middle = func(vals, axis=0, skipna=skipna, min_count=0)
        else:
            middle = func(vals, axis=0, skipna=skipna)
        if result is None:
            result = middle.copy()
        else:
            result = ufunc(result, middle)
    if name in ('sum', 'prod', 'mean'):
        if (min_count > 0 or name == 'mean') and result is not None:
            non_null_count = np.zeros(len(self), dtype=np.intp)
            for block in self._mgr.blocks:
                vals = block.values
                if vals.dtype.kind in 'biu':
                    non_null_count += vals.shape[0]
                else:
                    non_null_count += vals.shape[0] - isna(vals).sum(axis=0)
            if name == 'mean':
                null_mask = non_null_count == 0
                result = result.astype('float64')
                result[~null_mask] /= non_null_count[~null_mask]
                result[null_mask] = np.nan
            else:
                null_mask = non_null_count < min_count
                if null_mask.any():
                    if result.dtype.kind not in 'fc':
                        result = result.astype('float64')
                    result[null_mask] = np.nan
    assert result is not None
    res_ser = self._constructor_sliced(result, index=self.index, copy=False)
    return res_ser

