@classmethod
def _register(cls) -> None:
    """
        Register upon first use instead of at import time, to avoid
        globally importing JAX.
        """
    if not cls._registered:
        import jax
        jax.tree_util.register_pytree_node(cls, lambda instance: pickle_flatten(instance, jax.Array), lambda aux_data, children: pickle_unflatten(children, aux_data))
        cls._registered = True

def _validate_key(ctx: click.Context, param: click.Parameter, param_24: t.Any) -> t.Any:
    """The ``--key`` option must be specified when ``--cert`` is a file.
    Modifies the ``cert`` param to be a ``(cert, key)`` pair if needed.
    """
    cert = ctx.params.get('cert')
    is_adhoc = cert == 'adhoc'
    try:
        import ssl
    except ImportError:
        is_context = False
    else:
        is_context = isinstance(cert, ssl.SSLContext)
    if param_24 is not None:
        if is_adhoc:
            raise click.BadParameter('When "--cert" is "adhoc", "--key" is not used.', ctx, param)
        if is_context:
            raise click.BadParameter('When "--cert" is an SSLContext object, "--key" is not used.', ctx, param)
        if not cert:
            raise click.BadParameter('"--cert" must also be specified.', ctx, param)
        ctx.params['cert'] = (cert, param_24)
    elif cert and (not (is_adhoc or is_context)):
        raise click.BadParameter('Required when using "--cert".', ctx, param)
    return param_24

def stack(frame: DataFrame, level=-1, dropna: bool=True, param_21: bool=True) -> Series | DataFrame:
    """
    Convert DataFrame to Series with multi-level Index. Columns become the
    second level of the resulting hierarchical index

    Returns
    -------
    stacked : Series or DataFrame
    """

    def stack_factorize(index):
        if index.is_unique:
            return (index, np.arange(len(index)))
        codes, categories = factorize_from_iterable(index)
        return (categories, codes)
    N, K = frame.shape
    level_num = frame.columns._get_level_number(level)
    if isinstance(frame.columns, MultiIndex):
        return _stack_multi_columns(frame, level_num=level_num, dropna=dropna, sort=param_21)
    elif isinstance(frame.index, MultiIndex):
        new_levels = list(frame.index.levels)
        new_codes = [lab.repeat(K) for lab in frame.index.codes]
        clev, clab = stack_factorize(frame.columns)
        new_levels.append(clev)
        new_codes.append(np.tile(clab, N).ravel())
        new_names = list(frame.index.names)
        new_names.append(frame.columns.name)
        new_index = MultiIndex(levels=new_levels, codes=new_codes, names=new_names, verify_integrity=False)
    else:
        levels, (ilab, clab) = zip(*map(stack_factorize, (frame.index, frame.columns)), strict=True)
        codes = (ilab.repeat(K), np.tile(clab, N).ravel())
        new_index = MultiIndex(levels=levels, codes=codes, names=[frame.index.name, frame.columns.name], verify_integrity=False)
    new_values: ArrayLike
    if not frame.empty and frame._is_homogeneous_type:
        dtypes = list(frame.dtypes._values)
        dtype = dtypes[0]
        if isinstance(dtype, ExtensionDtype):
            arr = dtype.construct_array_type()
            new_values = arr._concat_same_type([col._values for _, col in frame.items()])
            new_values = _reorder_for_extension_array_stack(new_values, N, K)
        else:
            new_values = frame._values.ravel()
    else:
        new_values = frame._values.ravel()
    if dropna:
        mask = notna(new_values)
        new_values = new_values[mask]
        new_index = new_index[mask]
    return frame._constructor_sliced(new_values, index=new_index)

def _parse_cell(cell_contents, cell_typ):
    """
            converts the contents of the cell into a pandas appropriate object
            """
    if cell_typ == XL_CELL_DATE:
        try:
            cell_contents = xldate.xldate_as_datetime(cell_contents, epoch1904)
        except OverflowError:
            return cell_contents
        year = cell_contents.timetuple()[0:3]
        if not epoch1904 and year == (1899, 12, 31) or (epoch1904 and year == (1904, 1, 1)):
            cell_contents = time(cell_contents.hour, cell_contents.minute, cell_contents.second, cell_contents.microsecond)
    elif cell_typ == XL_CELL_ERROR:
        cell_contents = np.nan
    elif cell_typ == XL_CELL_BOOLEAN:
        cell_contents = bool(cell_contents)
    elif cell_typ == XL_CELL_NUMBER:
        if math.isfinite(cell_contents):
            val = int(cell_contents)
            if val == cell_contents:
                cell_contents = val
    return cell_contents

def compare(x, y):
    """Returns the result of the loose comparison between x and y)."""
    return approx(x, y, rtol=10.0 ** (-decimal))

def get_locs(self, seq) -> npt.NDArray[np.intp]:
    """
        Get location for a sequence of labels.

        This method returns the integer positions in the index that match the
        given sequence of per-level keys, slices, or boolean masks.

        Parameters
        ----------
        seq : label, slice, list, mask or a sequence of such
           You should use one of the above for each level.
           If a level should not be used, set it to ``slice(None)``.

        Returns
        -------
        numpy.ndarray
            NumPy array of integers suitable for passing to iloc.

        See Also
        --------
        MultiIndex.get_loc : Get location for a label or a tuple of labels.
        MultiIndex.slice_locs : Get slice location given start label(s) and
                                end label(s).

        Examples
        --------
        >>> mi = pd.MultiIndex.from_arrays([list("abb"), list("def")])

        >>> mi.get_locs("b")  # doctest: +SKIP
        array([1, 2], dtype=int64)

        >>> mi.get_locs([slice(None), ["e", "f"]])  # doctest: +SKIP
        array([1, 2], dtype=int64)

        >>> mi.get_locs([[True, False, True], slice("e", "f")])  # doctest: +SKIP
        array([2], dtype=int64)
        """
    true_slices = [i for i, s in enumerate(com.is_true_slices(seq)) if s]
    if true_slices and true_slices[-1] >= self._lexsort_depth:
        raise UnsortedIndexError(f'MultiIndex slicing requires the index to be lexsorted: slicing on levels {true_slices}, lexsort depth {self._lexsort_depth}')
    if any((x is Ellipsis for x in seq)):
        raise NotImplementedError('MultiIndex does not support indexing with Ellipsis')
    n = len(self)

    def _to_bool_indexer(indexer) -> npt.NDArray[np.bool_]:
        if isinstance(indexer, slice):
            new_indexer = np.zeros(n, dtype=np.bool_)
            new_indexer[indexer] = True
            return new_indexer
        return indexer
    indexer: npt.NDArray[np.bool_] | None = None
    for i, k in enumerate(seq):
        lvl_indexer: npt.NDArray[np.bool_] | slice | None = None
        if com.is_bool_indexer(k):
            if len(k) != n:
                raise ValueError('cannot index with a boolean indexer that is not the same length as the index')
            if isinstance(k, (ABCSeries, Index)):
                k = k._values
            lvl_indexer = np.asarray(k)
            if indexer is None:
                lvl_indexer = lvl_indexer.copy()
        elif is_list_like(k):
            try:
                lvl_indexer = self._get_level_indexer(k, level=i, indexer=indexer)
            except (InvalidIndexError, TypeError, KeyError) as err:
                if any((not is_hashable(x) for x in k)):
                    raise err
                level_codes = self.codes[i]
                k_codes = self.levels[i].get_indexer(k)
                k_isna = isna(k if not isinstance(k, tuple) else list(k))
                na_count = k_isna.sum()
                missing_mask = k_codes == -1
                if na_count:
                    if missing_mask.sum() > na_count:
                        raise KeyError(k) from None
                    if not lib.has_sentinel(level_codes, -1):
                        raise KeyError(k) from None
                elif missing_mask.any():
                    raise KeyError(k) from None
                k_codes = k_codes[~missing_mask]
                lvl_indexer = algos.isin(level_codes, k_codes)
                if na_count:
                    lvl_indexer = lvl_indexer | (level_codes == -1)
            if lvl_indexer is None:
                return np.array([], dtype=np.intp)
        elif com.is_null_slice(k):
            if indexer is None and i == len(seq) - 1:
                return np.arange(n, dtype=np.intp)
            continue
        else:
            lvl_indexer = self._get_level_indexer(k, level=i, indexer=indexer)
        lvl_indexer = _to_bool_indexer(lvl_indexer)
        if indexer is None:
            indexer = lvl_indexer
        else:
            indexer &= lvl_indexer
            if not np.any(indexer) and np.any(lvl_indexer):
                raise KeyError(seq)
    if indexer is None:
        return np.array([], dtype=np.intp)
    pos_indexer = indexer.nonzero()[0]
    return self._reorder_indexer(seq, pos_indexer)

def _concatenate_predictions(self, X, predictions):
    """Concatenate the predictions of each first layer learner and
        possibly the input dataset `X`.

        If `X` is sparse and `self.passthrough` is False, the output of
        `transform` will be dense (the predictions). If `X` is sparse
        and `self.passthrough` is True, the output of `transform` will
        be sparse.

        This helper is in charge of ensuring the predictions are 2D arrays and
        it will drop one of the probability column when using probabilities
        in the binary case. Indeed, the p(y|c=0) = 1 - p(y|c=1)

        When `y` type is `"multilabel-indicator"`` and the method used is
        `predict_proba`, `preds` can be either a `ndarray` of shape
        `(n_samples, n_class)` or for some estimators a list of `ndarray`.
        This function will drop one of the probability column in this situation as well.
        """
    X_meta = []
    for est_idx, preds in enumerate(predictions):
        if isinstance(preds, list):
            for pred in preds:
                X_meta.append(pred[:, 1:])
        elif preds.ndim == 1:
            X_meta.append(preds.reshape(-1, 1))
        elif self.stack_method_[est_idx] == 'predict_proba' and len(self.classes_) == 2:
            X_meta.append(preds[:, 1:])
        else:
            X_meta.append(preds)
    self._n_feature_outs = [pred.shape[1] for pred in X_meta]
    if self.passthrough:
        X_meta.append(X)
        if sparse.issparse(X):
            return sparse.hstack(X_meta, format=X.format)
    return np.hstack(X_meta)

