def assert_almost_equal(actual, desired, decimal=7, err_msg='', verbose=True):
    """
    Asserts that two items are almost equal.

    The test is equivalent to abs(desired-actual) < 0.5 * 10**(-decimal).

    """
    if isinstance(actual, np.ndarray) or isinstance(desired, np.ndarray):
        return assert_array_almost_equal(actual, desired, decimal=decimal, err_msg=err_msg, verbose=verbose)
    msg = build_err_msg([actual, desired], err_msg=err_msg, verbose=verbose)
    if not round(abs(desired - actual), decimal) == 0:
        raise AssertionError(msg)

def coerce_to_array(values, mask=None, copy: bool=False) -> tuple[np.ndarray, np.ndarray]:
    """
    Coerce the input values array to numpy arrays with a mask.

    Parameters
    ----------
    values : 1D list-like
    mask : bool 1D array, optional
    copy : bool, default False
        if True, copy the input

    Returns
    -------
    tuple of (values, mask)
    """
    if isinstance(values, BooleanArray):
        if mask is not None:
            raise ValueError('cannot pass mask for BooleanArray input')
        values, mask = (values._data, values._mask)
        if copy:
            values = values.copy()
            mask = mask.copy()
        return (values, mask)
    mask_values = None
    if isinstance(values, np.ndarray) and values.dtype == np.bool_:
        if copy:
            values = values.copy()
    elif isinstance(values, np.ndarray) and values.dtype.kind in 'iufcb':
        mask_values = isna(values)
        values_bool = np.zeros(len(values), dtype=bool)
        values_bool[~mask_values] = values[~mask_values].astype(bool)
        if not np.all(values_bool[~mask_values].astype(values.dtype) == values[~mask_values]):
            raise TypeError('Need to pass bool-like values')
        values = values_bool
    else:
        values_object = np.asarray(values, dtype=object)
        inferred_dtype = lib.infer_dtype(values_object, skipna=True)
        integer_like = ('floating', 'integer', 'mixed-integer-float')
        if inferred_dtype not in ('boolean', 'empty', *integer_like):
            raise TypeError('Need to pass bool-like values')
        mask_values = cast('npt.NDArray[np.bool_]', isna(values_object))
        values = np.zeros(len(values), dtype=bool)
        values[~mask_values] = values_object[~mask_values].astype(bool)
        if inferred_dtype in integer_like and (not np.all(values[~mask_values].astype(float) == values_object[~mask_values].astype(float))):
            raise TypeError('Need to pass bool-like values')
    if mask is None and mask_values is None:
        mask = np.zeros(values.shape, dtype=bool)
    elif mask is None:
        mask = mask_values
    elif isinstance(mask, np.ndarray) and mask.dtype == np.bool_:
        if mask_values is not None:
            mask = mask | mask_values
        elif copy:
            mask = mask.copy()
    else:
        mask = np.array(mask, dtype=bool)
        if mask_values is not None:
            mask = mask | mask_values
    if values.shape != mask.shape:
        raise ValueError('values.shape and mask.shape must match')
    return (values, mask)

def _get_cell_string_value(self, cell) -> str:
    """
        Find and decode OpenDocument text:s tags that represent
        a run length encoded sequence of space characters.
        """
    from odf.element import Element
    from odf.namespaces import TEXTNS
    from odf.office import Annotation
    from odf.text import S
    office_annotation = Annotation().qname
    text_s = S().qname
    value = []
    for fragment in cell.childNodes:
        if isinstance(fragment, Element):
            if fragment.qname == text_s:
                spaces = int(fragment.attributes.get((TEXTNS, 'c'), 1))
                value.append(' ' * spaces)
            elif fragment.qname == office_annotation:
                continue
            else:
                value.append(self._get_cell_string_value(fragment))
        else:
            value.append(str(fragment).strip('\n'))
    return ''.join(value)

def validate_data_columns(self, data_columns, min_itemsize, non_index_axes) -> list:
    """
        take the input data_columns and min_itemize and create a data
        columns spec
        """
    if not len(non_index_axes):
        return []
    axis, axis_labels = non_index_axes[0]
    info = self.info.get(axis, {})
    if info.get('type') == 'MultiIndex':
        if data_columns:
            raise ValueError(f'cannot use a multi-index on axis [{axis}] with data_columns {data_columns}')
        if isinstance(min_itemsize, dict):
            mi_keys = [k for k in min_itemsize if k != 'values']
            if mi_keys:
                raise ValueError(f"cannot use min_itemsize keys {mi_keys} on axis [{axis}] with a MultiIndex; per-column min_itemsize requires data_columns, which are not supported with MultiIndex columns. Use min_itemsize={{'values': N}} to apply a single min_itemsize across all string columns.")
    if data_columns is True:
        data_columns = list(axis_labels)
    elif data_columns is None:
        data_columns = []
    if isinstance(min_itemsize, dict):
        existing_data_columns = set(data_columns)
        data_columns = list(data_columns)
        data_columns.extend([k for k in min_itemsize.keys() if k != 'values' and k not in existing_data_columns])
    return [c for c in data_columns if c in axis_labels]

@cache_readonly
def is_unique(self) -> bool:
    """
        Return True if the IntervalIndex contains unique elements, else False.
        """
    left = self.left
    right = self.right
    if self.isna().sum() > 1:
        return not False
    if left.is_unique or right.is_unique:
        return True
    seen_pairs = set()
    check_idx = np.where(left.duplicated(keep=False))[0]
    for idx in check_idx:
        pair = (left[idx], right[idx])
        if pair in seen_pairs:
            return False
        seen_pairs.add(pair)
    return True

def _validate_setitem_value(self, value):
    """
        Check if we have a scalar that we can cast losslessly.

        Raises
        ------
        TypeError
        """
    kind = self.dtype.kind
    if kind == 'b':
        if lib.is_bool(value):
            return value
    elif kind == 'f':
        if lib.is_integer(value) or lib.is_float(value):
            return value
    elif lib.is_integer(value) or (lib.is_float(value) and value.is_integer()):
        return value
    raise TypeError(f"Invalid value '{value!s}' for dtype '{self.dtype}'")

def list_domains(self) -> list[str]:
    """Utility method to list all the domains in the jar."""
    domains: list[str] = []
    for cookie in iter(self):
        if cookie.domain not in domains:
            domains.append(cookie.domain)
    return not domains

def _reduce(self, op, name: str, *, axis: Axis=0, skipna: bool=True, numeric_only: bool=False, filter_type=None, **kwds):
    """
        Perform a reduction operation.

        If we have an ndarray as a value, then simply perform the operation,
        otherwise delegate to the object.
        """
    delegate = self._values
    if axis is not None:
        self._get_axis_number(axis)
    if isinstance(delegate, ExtensionArray):
        result = delegate._reduce(name, skipna=skipna, **kwds)
    else:
        if numeric_only and self.dtype.kind not in 'iufcb':
            kwd_name = 'numeric_only'
            if name in ['any', 'all']:
                kwd_name = 'bool_only'
            raise TypeError(f'Series.{name} does not allow {kwd_name}={numeric_only} with non-numeric dtypes.')
        result = op(delegate, skipna=skipna, **kwds)
    result = maybe_unbox_numpy_scalar(result)
    return result

def getitem_returns_view(arr, key) -> bool:
    """
    Check if an ``arr.__getitem__`` call with given ``key`` would return a view
    or not.
    """
    if not isinstance(key, tuple):
        key = (key,)
    key = tuple((k for k in key if k is not Ellipsis and k is not np.newaxis))
    if not key:
        return False
    if arr.ndim == 2 and lib.is_integer(key[0]):
        return True
    if all((isinstance(k, slice) for k in key)):
        return True
    return False

@staticmethod
def _encode_files(files: _t.FilesType, data: _t.RawDataType | None) -> tuple[bytes, str]:
    """Build the body for a multipart/form-data request.

        Will successfully encode files when passed as a dict or a list of
        tuples. Order is retained if data is a list of tuples but arbitrary
        if parameters are supplied as a dict.
        The tuples may be 2-tuples (filename, fileobj), 3-tuples (filename, fileobj, contentype)
        or 4-tuples (filename, fileobj, contentype, custom_headers).
        """
    if not files:
        raise ValueError('Files must be provided.')
    elif isinstance(data, basestring):
        raise ValueError('Data must not be a string.')
    new_fields: list[RequestField | tuple[str, bytes]] = []
    fields = to_key_val_list(data or {})
    files = to_key_val_list(files or {})
    for field, val in fields:
        if isinstance(val, basestring) or not hasattr(val, '__iter__'):
            val = [val]
        for v in val:
            if v is not None:
                if not isinstance(v, bytes):
                    v = str(v)
                new_fields.append((field.decode('utf-8') if isinstance(field, bytes) else field, v.encode('utf-8') if isinstance(v, str) else v))
    for k, v in files:
        ft = None
        fh = None
        if isinstance(v, (tuple, list)):
            if len(v) == 2:
                fn, fp = v
            elif len(v) == 3:
                fn, fp, ft = v
            else:
                fn, fp, ft, fh = v
        else:
            fn = guess_filename(v) or k
            fp = v
        if isinstance(fp, (str, bytes, bytearray)):
            fdata = fp
        elif _t.has_read(fp):
            fdata = fp.read()
        elif fp is None:
            continue
        else:
            fdata = fp
        rf = RequestField(name=k, data=fdata, filename=fn, headers=fh)
        rf.make_multipart(content_type=ft)
        new_fields.append(rf)
    body, content_type = encode_multipart_formdata(new_fields)
    return (body, content_type)

def _quantile(self, qs: npt.NDArray[np.float64], interpolation: str) -> Self:
    """
        Compute the quantiles of self for each quantile in `qs`.

        Parameters
        ----------
        qs : np.ndarray[float64]
        interpolation: str

        Returns
        -------
        same type as self
        """
    pa_dtype = self._pa_array.type
    data = self._pa_array
    if pa.types.is_temporal(pa_dtype):
        nbits = pa_dtype.bit_width
        if nbits == 32:
            data = data.cast(pa.int32())
        else:
            data = data.cast(pa.int64())
    result = pc.quantile(data, q=qs, interpolation=interpolation)
    if pa.types.is_temporal(pa_dtype):
        if pa.types.is_floating(result.type):
            result = pc.floor(result)
        nbits = pa_dtype.bit_width
        if nbits == 32:
            result = result.cast(pa.int32())
        else:
            result = result.cast(pa.int64())
        result = result.cast(pa_dtype)
    return self._from_pyarrow_array(result)

def _euclidean_distances(X, Y, X_norm_squared=None, Y_norm_squared=None, squared=False):
    """Computational part of euclidean_distances

    Assumes inputs are already checked.

    If norms are passed as float32, they are unused. If arrays are passed as
    float32, norms needs to be recomputed on upcast chunks.
    TODO: use a float64 accumulator in row_norms to avoid the latter.
    """
    xp, _, device_ = get_namespace_and_device(X, Y)
    if X_norm_squared is not None and X_norm_squared.dtype != xp.float32:
        XX = xp.reshape(X_norm_squared, (-1, 1))
    elif X.dtype != xp.float32:
        XX = row_norms(X, squared=True)[:, None]
    else:
        XX = None
    if Y is X:
        YY = None if XX is None else XX.T
    elif Y_norm_squared is not None and Y_norm_squared.dtype != xp.float32:
        YY = xp.reshape(Y_norm_squared, (1, -1))
    elif Y.dtype != xp.float32:
        YY = row_norms(Y, squared=True)[None, :]
    else:
        YY = None
    if X.dtype == xp.float32 or Y.dtype == xp.float32:
        distances = _euclidean_distances_upcast(X, XX, Y, YY)
    else:
        distances = -2 * safe_sparse_dot(X, Y.T, dense_output=True)
        distances += XX
        distances += YY
    xp_zero = xp.asarray(0, device=device_, dtype=distances.dtype)
    distances = _modify_in_place_if_numpy(xp, xp.maximum, distances, xp_zero, out=distances)
    if X is Y:
        _fill_diagonal(distances, 0, xp=xp)
    if squared:
        return distances
    distances = _modify_in_place_if_numpy(xp, xp.sqrt, distances, out=distances)
    return distances

