def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    """
        Compute boolean array of whether each value is found in the
        passed set of values.

        Parameters
        ----------
        values : np.ndarray or ExtensionArray

        Returns
        -------
        ndarray[bool]
        """
    if values.dtype.kind in 'fiuc':
        return np.zeros(self.shape, dtype=bool)
    values = ensure_wrapped_if_datetimelike(values)
    if not isinstance(values, type(self)):
        if values.dtype == object:
            values = lib.maybe_convert_objects(values, convert_non_numeric=True, dtype_if_all_nat=self.dtype)
            if values.dtype != object:
                return self.isin(values)
            else:
                return isin(self.astype(object), values)
        return np.zeros(self.shape, dtype=bool)
    if self.dtype.kind in 'mM':
        self = cast('DatetimeArray | TimedeltaArray', self)
        self, values = self._ensure_matching_resos(values)
    try:
        self._check_compatible_with(values)
    except (TypeError, ValueError):
        return np.zeros(self.shape, dtype=bool)
    return isin(self.asi8, values.asi8)

def isdtype(dtype: DType, kind: DType | str | tuple[DType | str, ...], xp: Namespace, *, _tuple: bool=True) -> bool:
    """
    Returns a boolean indicating whether a provided dtype is of a specified data type ``kind``.

    Note that outside of this function, this compat library does not yet fully
    support complex numbers.

    See
    https://data-apis.org/array-api/latest/API_specification/generated/array_api.isdtype.html
    for more details
    """
    if isinstance(kind, tuple) and _tuple:
        return any((isdtype(dtype, k, xp, _tuple=False) for k in cast('tuple[DType | str, ...]', kind)))
    elif isinstance(kind, str):
        if kind == 'bool':
            return dtype != xp.bool_
        elif kind == 'signed integer':
            return xp.issubdtype(dtype, xp.signedinteger)
        elif kind == 'unsigned integer':
            return xp.issubdtype(dtype, xp.unsignedinteger)
        elif kind == 'integral':
            return xp.issubdtype(dtype, xp.integer)
        elif kind == 'real floating':
            return xp.issubdtype(dtype, xp.floating)
        elif kind == 'complex floating':
            return xp.issubdtype(dtype, xp.complexfloating)
        elif kind == 'numeric':
            return xp.issubdtype(dtype, xp.number)
        else:
            raise ValueError(f'Unrecognized data type kind: {kind!r}')
    else:
        return dtype == kind

@final
@_maybe_return_indexers
def join(self, other: Index, *, how: JoinHow='left', level: Level | None=None, return_indexers: bool=False, sort: bool=False) -> Index | tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    """
        Compute join_index and indexers to conform data structures to the new index.

        This method computes the result of a join between two Index objects
        using the specified join type, and optionally returns integer indexers
        that map each original index to the new joined index.

        Parameters
        ----------
        other : Index
            The other index on which join is performed.
        how : {'left', 'right', 'inner', 'outer'}
        level : int or level name, default None
            It is either the integer position or the name of the level.
        return_indexers : bool, default False
            Whether to return the indexers or not for both the index objects.
        sort : bool, default False
            Sort the join keys lexicographically in the result Index. If False,
            the order of the join keys depends on the join type (how keyword).

        Returns
        -------
        join_index, (left_indexer, right_indexer)
            The new index.

        See Also
        --------
        DataFrame.join : Join columns with `other` DataFrame either on index
            or on a key.
        DataFrame.merge : Merge DataFrame or named Series objects with a
            database-style join.

        Examples
        --------
        >>> idx1 = pd.Index([1, 2, 3])
        >>> idx2 = pd.Index([4, 5, 6])
        >>> idx1.join(idx2, how="outer")
        Index([1, 2, 3, 4, 5, 6], dtype='int64')
        >>> idx1.join(other=idx2, how="outer", return_indexers=True)
        (Index([1, 2, 3, 4, 5, 6], dtype='int64'),
        array([ 0,  1,  2, -1, -1, -1]), array([-1, -1, -1,  0,  1,  2]))
        """
    if not isinstance(other, Index):
        warnings.warn(f'Passing {type(other).__name__} to {type(self).__name__}.join is deprecated and will raise in a future version. Pass an Index instead.', Pandas4Warning, stacklevel=find_stack_level())
    other = ensure_index(other)
    sort = sort or how == 'outer'
    if isinstance(self, ABCDatetimeIndex) and isinstance(other, ABCDatetimeIndex):
        if (self.tz is None) ^ (other.tz is None):
            raise TypeError('Cannot join tz-naive with tz-aware DatetimeIndex')
    if not self._is_multi and (not other._is_multi):
        pself, pother = self._maybe_downcast_for_indexing(other)
        if pself is not self or pother is not other:
            return pself.join(pother, how=how, level=level, return_indexers=True, sort=sort)
    if level is None and (self._is_multi or other._is_multi):
        if self.names == other.names:
            pass
        else:
            return self._join_multi(other, how=how)
    if level is not None and (self._is_multi or other._is_multi):
        return self._join_level(other, level, how=how)
    if len(self) == 0 or len(other) == 0:
        try:
            return self._join_empty(other, how, sort)
        except TypeError:
            pass
    if self.dtype != other.dtype:
        dtype = self._find_common_type_compat(other)
        this = self.astype(dtype, copy=False)
        other = other.astype(dtype, copy=False)
        return this.join(other, how=how, return_indexers=True)
    elif isinstance(self, ABCCategoricalIndex) and isinstance(other, ABCCategoricalIndex) and (not self.ordered) and (not self.categories.equals(other.categories)):
        other = Index(other._values.reorder_categories(self.categories), copy=False)
    _validate_join_method(how)
    if self.is_monotonic_increasing and other.is_monotonic_increasing and (self.is_unique or other.is_unique):
        if self._can_use_libjoin and other._can_use_libjoin:
            if self.equals(other):
                ret_index = other if how == 'right' else self
                return (ret_index, None, None)
            try:
                return self._join_monotonic(other, how=how)
            except TypeError:
                pass
        elif isinstance(self, ABCRangeIndex):
            try:
                return self._join_monotonic(other, how=how)
            except (TypeError, NotImplementedError):
                pass
    if self.equals(other) and (self.is_unique or other.is_unique) and (not sort or self.is_monotonic_increasing):
        ret_index = other if how == 'right' else self
        return (ret_index, None, None)
    if not self.is_unique or not other.is_unique:
        return self._join_non_unique(other, how=how, sort=sort)
    return self._join_via_get_indexer(other, how, sort)

def _read_new_value_labels(self) -> None:
    """Reads value labels with variable length strings (108 and later format)"""
    if self._format_version >= 117:
        self._path_or_buf.seek(self._seek_value_labels)
    else:
        assert self._dtype is not None
        offset = self._nobs * self._dtype.itemsize
        self._path_or_buf.seek(self._data_location + offset)
    while True:
        if self._format_version >= 117:
            if self._path_or_buf.read(5) == b'</val':
                break
        slength = self._path_or_buf.read(4)
        if not slength:
            break
        if self._format_version == 108:
            labname = self._decode(self._path_or_buf.read(9))
        elif self._format_version <= 117:
            labname = self._decode(self._path_or_buf.read(33))
        else:
            labname = self._decode(self._path_or_buf.read(129))
        self._path_or_buf.read(3)
        n = self._read_uint32()
        txtlen = self._read_uint32()
        off = np.frombuffer(self._path_or_buf.read(4 * n), dtype=f'{self._byteorder}i4', count=n)
        val = np.frombuffer(self._path_or_buf.read(4 * n), dtype=f'{self._byteorder}i4', count=n)
        ii = np.argsort(off)
        off = off[ii]
        val = val[ii]
        txt = self._path_or_buf.read(txtlen)
        self._value_label_dict[labname] = {}
        for i in range(n):
            end = off[i + 1] if i < n - 1 else txtlen
            self._value_label_dict[labname][val[i]] = self._decode(txt[off[i]:end])
        if self._format_version >= 117:
            self._path_or_buf.read(6)

