def _find_error_handler(self, e: Exception, blueprints: list[str]) -> ft.ErrorHandlerCallable | None:
    """Return a registered error handler for an exception in this order:
        blueprint handler for a specific code, app handler for a specific code,
        blueprint handler for an exception class, app handler for an exception
        class, or ``None`` if a suitable handler is not found.
        """
    exc_class, code = self._get_exc_class_and_code(type(e))
    names = (*blueprints, None)
    for c in (code, None) if code is not None else (None,):
        for name in names:
            handler_map = self.error_handler_spec[name][c]
            if not handler_map:
                continue
            for cls in exc_class.__mro__:
                handler = handler_map.get(cls)
                if handler is not None:
                    return handler
    return None

def _check_large_sparse(X, accept_large_sparse=False):
    """Raise a ValueError if X has 64bit indices and accept_large_sparse=False"""
    if not accept_large_sparse:
        supported_indices = ['int32']
        if X.format == 'coo':
            index_keys = ['col', 'row']
        elif X.format in ['csr', 'csc', 'bsr']:
            index_keys = ['indices', 'indptr']
        else:
            return
        for key in index_keys:
            indices_datatype = getattr(X, key).dtype
            if indices_datatype not in supported_indices:
                raise ValueError(f'Only sparse matrices with 32-bit integer indices are accepted. Got {indices_datatype} indices. Please do report a minimal reproducer on scikit-learn issue tracker so that support for your use-case can be studied by maintainers. See: https://scikit-learn.org/dev/developers/minimal_reproducer.html')

def _ravel_and_check_weights(a, param_95):
    """ Check a and weights have matching shapes, and ravel both """
    a = np.asarray(a)
    if a.dtype == np.bool:
        msg = f'Converting input from {a.dtype} to {np.uint8} for compatibility.'
        warnings.warn(msg, RuntimeWarning, stacklevel=3)
        a = a.astype(np.uint8)
    if param_95 is not None:
        param_95 = np.asarray(param_95)
        if param_95.shape != a.shape:
            raise ValueError('weights should have the same shape as a.')
        param_95 = param_95.ravel()
    a = a.ravel()
    return (a, param_95)

def _apply(self, func: Callable[..., Any], name: str, param_17: bool=False, numba_args: tuple[Any, ...]=(), **kwargs):
    """
        Rolling statistical measure using supplied function.

        Designed to be used with passed-in Cython array-based functions.

        Parameters
        ----------
        func : callable function to apply
        name : str,
        numba_args : tuple
            args to be passed when func is a numba func
        **kwargs
            additional arguments for rolling function and window function

        Returns
        -------
        y : type of input
        """
    window_indexer = self._get_window_indexer()
    min_periods = self.min_periods if self.min_periods is not None else window_indexer.window_size

    def homogeneous_func(values: np.ndarray):
        if values.size == 0:
            return values.copy()

        def calc(x):
            start, end = window_indexer.get_window_bounds(num_values=len(x), min_periods=min_periods, center=self.center, closed=self.closed, step=self.step)
            self._check_window_bounds(start, end, len(x))
            return func(x, start, end, min_periods, *numba_args)
        with np.errstate(all='ignore'):
            result = calc(values)
        return result
    if self.method == 'single':
        return self._apply_columnwise(homogeneous_func, name, param_17)
    else:
        return self._apply_tablewise(homogeneous_func, name, param_17)

