def is_valid_cidr(string_network: str) -> bool:
    """
    Very simple check of the cidr format in no_proxy variable.

    :rtype: bool
    """
    if string_network.count('/') == 1:
        try:
            mask = int(string_network.split('/')[1])
        except ValueError:
            return False
        if mask < 1 or mask > 32:
            return False
        try:
            socket.inet_aton(string_network.split('/')[0])
        except OSError:
            return False
    else:
        return False
    return True

def _read_old_value_labels(self) -> None:
    """Reads value labels with fixed-length strings (105 and earlier format)"""
    assert self._dtype is not None
    offset = self._nobs * self._dtype.itemsize
    self._path_or_buf.seek(self._data_location + offset)
    while True:
        if not self._path_or_buf.read(2):
            break
        self._path_or_buf.seek(-2, os.SEEK_CUR)
        n = self._read_uint16()
        labname = self._decode(self._path_or_buf.read(9))
        self._path_or_buf.read(1)
        codes = np.frombuffer(self._path_or_buf.read(2 * n), dtype=f'{self._byteorder}i2', count=n)
        self._value_label_dict[labname] = {}
        for i in range(n):
            self._value_label_dict[labname][codes[i]] = self._decode(self._path_or_buf.read(8))

def weekend_to_monday(param_98: datetime) -> datetime:
    """
    If holiday falls on Sunday or Saturday,
    use day thereafter (Monday) instead.
    Needed for holidays such as Christmas observation in Europe
    """
    if param_98.weekday() == 6:
        return param_98 + timedelta(1)
    elif param_98.weekday() == 5:
        return param_98 + timedelta(2)
    return param_98

@no_type_check
def _apply(self, f, *args, **kwargs):
    """
        Dispatch to _upsample; we are stripping all of the _upsample kwargs and
        performing the original function call on the grouped object.
        """

    def func(x):
        x = self._resampler_cls(x, timegrouper=self._timegrouper, gpr_index=self.ax)
        if isinstance(f, str):
            return f
        return x.apply(f, *args, **kwargs)
    result = self._groupby.apply(func)
    if isinstance(result, ABCDataFrame) and len(result) == 0 and (not isinstance(result.index, PeriodIndex)):
        result = result.set_index(_asfreq_compat(self.obj.index[:0], freq=self.freq), append=True)
    return self._wrap_result(result)

def match_request(self) -> None:
    """Apply routing to the current request, storing either the matched
        endpoint and args, or a routing exception.
        """
    try:
        result = self.url_adapter.match(return_rule=True)
    except HTTPException as e:
        self._request.routing_exception = e
    else:
        self._request.url_rule, self._request.view_args = result

def _ezclump(handle):
    """
    Finds the clumps (groups of data with the same values) for a 1D bool array.

    Returns a series of slices.
    """
    if handle.ndim > 1:
        handle = handle.ravel()
    idx = (handle[1:] ^ handle[:-1]).nonzero()
    idx = idx[0] + 1
    if handle[0]:
        if len(idx) == 0:
            return [slice(0, handle.size)]
        r = [slice(0, idx[0])]
        r.extend((slice(left, right) for left, right in zip(idx[1:-1:2], idx[2::2])))
    else:
        if len(idx) == 0:
            return []
        r = [slice(left, right) for left, right in zip(idx[:-1:2], idx[1::2])]
    if handle[-1]:
        r.append(slice(idx[-1], handle.size))
    return r

def setitem(self, indexer, value) -> Block:
    """
        Attempt self.values[indexer] = value, possibly creating a new array.

        Parameters
        ----------
        indexer : tuple, list-like, array-like, slice, int
            The subset of self.values to set
        value : object
            The value being set

        Returns
        -------
        Block

        Notes
        -----
        `indexer` is a direct slice/positional indexer. `value` must
        be a compatible shape.
        """
    value = self._standardize_fill_value(value)
    values = cast('np.ndarray', self.values)
    if self.ndim == 2:
        values = values.T
    check_setitem_lengths(indexer, value, values)
    if self.dtype != _dtype_obj:
        value = extract_array(value, extract_numpy=True)
    try:
        casted = np_can_hold_element(values.dtype, value)
    except LossySetitemError:
        nb = self.coerce_to_target_dtype(value, raise_on_upcast=True)
        return nb.setitem(indexer, value)
    else:
        if self.dtype == _dtype_obj and (not is_scalar_indexer(indexer, values.ndim)):
            if isinstance(indexer, (ABCSeries, ABCIndex, np.ndarray, list, range, slice)):
                num_set = length_of_indexer(indexer, values)
            else:
                num_set = len(values[indexer])
            casted = setitem_datetimelike_compat(values, num_set, casted)
            if isinstance(casted, list) and len(casted) > 0 and isinstance(casted[0], (tuple, list, np.ndarray)):
                casted = construct_1d_object_array_from_listlike(casted)
        self = self._maybe_copy(inplace=True)
        values = cast('np.ndarray', self.values.T)
        if isinstance(casted, np.ndarray) and casted.ndim == 1 and (len(casted) == 1):
            casted = casted[0, ...]
        try:
            values[indexer] = casted
        except (TypeError, ValueError) as err:
            if is_list_like(casted):
                raise ValueError('setting an array element with a sequence.') from err
            raise
    return self

