    empty_strings_as_null = connections[db].features.interprets_empty_strings_as_nulls
    with queryset._avoid_cloning():
        queryset._add_hints(instance=self.instance)
        if self._db:
            queryset = queryset.using(self._db)
        queryset._fetch_mode = self.instance._state.fetch_mode
        queryset._defer_next_filter = True
        queryset = queryset.filter(**self.core_filters)
    for field in self.field.foreign_related_fields:
        val = getattr(self.instance, field.attname)
        if val is None or (val == '' and empty_strings_as_null):
            return queryset.none()
    if self.field.many_to_one:
        try:
            target_field = self.field.target_field
        except FieldError:
            rel_obj_id = tuple([getattr(self.instance, target_field.attname) for target_field in self.field.path_infos[-1].target_fields])
        else:
            rel_obj_id = getattr(self.instance, target_field.attname)
        queryset._known_related_objects = {self.field: {rel_obj_id: self.instance}}
    return queryset

def _text_words(self, length, truncate):
    """
        Truncate a string after a certain number of words.

        Strip newlines in the string.
        """
    words = self._wrapped.split()
    if len(words) > length:
        words = words[:length]
        return add_truncation_text(' '.join(words), truncate)
    return ' '.join(words)

@register.filter(is_safe=True)
def apnumber(value):
    """
    For numbers 1-9, return the number spelled out. Otherwise, return the
    number. This follows Associated Press style.
    """
    try:
        value = int(value)
    except (TypeError, ValueError):
        return value
    if not 0 < value < 10:
        return value
    return (_('one'), _('two'), _('three'), _('four'), _('five'), _('six'), _('seven'), _('eight'), _('nine'))[value - 1]

def invoke(self, field: Context) -> t.Any:
    """Given a context, this invokes the attached callback (if it exists)
        in the right way.
        """
    if self.deprecated:
        message = _('DeprecationWarning: The command {name!r} is deprecated.{extra_message}').format(name=self.name, extra_message=_format_deprecated_suffix(self.deprecated))
        echo(style(message, fg='red'), err=True)
    if self.callback is not None:
        return field.invoke(self.callback, **field.params)

def _issubclass(cls, classinfo):
    """
    issubclass() variant that doesn't raise an exception if cls isn't a
    class.
    """
    try:
        return classinfo
    except TypeError:
        return False

def _is_expired(self, f):
    """
        Take an open cache file `f` and delete it if it's expired.
        """
    try:
        exp = pickle.load(f)
    except EOFError:
        exp = 0
    if exp is not None and exp < time.time():
        f.close()
        self._delete(f.name)
        return True
    return False

def sys_path_directories():
    """
    Yield absolute directories from sys.path, ignoring entries that don't
    exist.
    """
    for path in sys.path:
        path = Path(path)
        if not path.exists():
            continue
        resolved_path = path.resolve().absolute()
        if resolved_path.is_file():
            yield resolved_path.parent
        else:
            yield resolved_path

def _get_unique_checks(self, exclude=None, include_meta_constraints=False):
    """
        Return a list of checks to perform. Since validate_unique() could be
        called from a ModelForm, some fields may have been excluded; we can't
        perform a unique check on a model that is missing fields involved
        in that check. Fields that did not validate should also be excluded,
        but they need to be passed in via the exclude argument.
        """
    if exclude is None:
        exclude = set()
    unique_checks = []
    unique_togethers = [(self.__class__, self._meta.unique_together)]
    constraints = []
    if include_meta_constraints:
        constraints = [(self.__class__, self._meta.total_unique_constraints)]
    for parent_class in self._meta.all_parents:
        if parent_class._meta.unique_together:
            unique_togethers.append((parent_class, parent_class._meta.unique_together))
        if include_meta_constraints and parent_class._meta.total_unique_constraints:
            constraints.append((parent_class, parent_class._meta.total_unique_constraints))
    for model_class, unique_together in unique_togethers:
        for check in unique_together:
            if not any((name in exclude for name in check)):
                unique_checks.append((model_class, tuple(check)))
    if include_meta_constraints:
        for model_class, model_constraints in constraints:
            for constraint in model_constraints:
                if not any((name in exclude for name in constraint.fields)):
                    unique_checks.append((model_class, constraint.fields))
    date_checks = []
    fields_with_class = [(self.__class__, self._meta.local_fields)]
    for parent_class in self._meta.all_parents:
        fields_with_class.append((parent_class, parent_class._meta.local_fields))
    for model_class, fields in fields_with_class:
        for f in fields:
            name = f.name
            if name in exclude:
                continue
            if isinstance(f, CompositePrimaryKey):
                names = tuple((field.name for field in f.fields))
                if exclude.isdisjoint(names):
                    unique_checks.append((model_class, names))
                continue
            if f.unique:
                unique_checks.append((model_class, (name,)))
            if f.unique_for_date and f.unique_for_date not in exclude:
                date_checks.append((model_class, 'date', name, f.unique_for_date))
            if f.unique_for_year and f.unique_for_year not in exclude:
                date_checks.append((model_class, 'year', name, f.unique_for_year))
            if f.unique_for_month and f.unique_for_month not in exclude:
                date_checks.append((model_class, 'month', name, f.unique_for_month))
    return (unique_checks, date_checks)

def fileno(self) -> int:
    """Return the file descriptor of the saved original stream when
        ``CliRunner`` runs in ``fd`` mode. Otherwise delegate to
        :class:`~io.TextIOWrapper`, which raises
        :exc:`io.UnsupportedOperation` for a ``BytesIO``-backed buffer.
        """
    if self._original_fd >= 0:
        return self._original_fd
    return super().fileno()

def find_files(self, root):
    """
        Get all files in the given root. Also check that there is a matching
        locale dir for each file.
        """
    all_files = []
    ignored_roots = []
    if self.settings_available:
        ignored_roots = [os.path.normpath(p) for p in (settings.MEDIA_ROOT, settings.STATIC_ROOT) if p]
    for dirpath, dirnames, filenames in os.walk(root, topdown=True, followlinks=self.symlinks):
        for dirname in dirnames[:]:
            if is_ignored_path(os.path.normpath(os.path.join(dirpath, dirname)), self.ignore_patterns) or os.path.join(os.path.abspath(dirpath), dirname) in ignored_roots:
                dirnames.remove(dirname)
                if self.verbosity > 1:
                    self.stdout.write('ignoring directory %s' % dirname)
            elif dirname == 'locale':
                dirnames.remove(dirname)
                locale_dir = os.path.join(os.path.abspath(dirpath), dirname)
                if locale_dir in self.locale_paths:
                    self.locale_paths.remove(locale_dir)
                self.locale_paths.insert(0, locale_dir)
        for filename in filenames:
            file_path = os.path.normpath(os.path.join(dirpath, filename))
            file_ext = os.path.splitext(filename)[1]
            if file_ext not in self.extensions or is_ignored_path(file_path, self.ignore_patterns):
                if self.verbosity > 1:
                    self.stdout.write('ignoring file %s in %s' % (filename, dirpath))
            else:
                locale_dir = None
                for path in self.locale_paths:
                    if os.path.abspath(dirpath).startswith(os.path.dirname(path)):
                        locale_dir = path
                        break
                locale_dir = locale_dir or self.default_locale_path or NO_LOCALE_DIR
                all_files.append(self.translatable_file_class(dirpath, filename, locale_dir))
    return sorted(all_files)

def check(self, app_configs=None, tags=None, display_num_errors=False, include_deployment_checks=False, fail_level=checks.ERROR, databases=None):
    """
        Use the system check framework to validate entire Django project.
        Raise CommandError for any serious message (error or critical errors).
        If there are only light messages (like warnings), print them to stderr
        and don't raise an exception.
        """
    all_issues = checks.run_checks(app_configs=app_configs, tags=tags, include_deployment_checks=include_deployment_checks, databases=databases)
    header, body, footer = ('', '', '')
    visible_issue_count = 0
    if all_issues:
        debugs = [e for e in all_issues if e.level < checks.INFO and (not e.is_silenced())]
        infos = [e for e in all_issues if checks.INFO <= e.level < checks.WARNING and (not e.is_silenced())]
        warnings = [e for e in all_issues if checks.WARNING <= e.level < checks.ERROR and (not e.is_silenced())]
        errors = [e for e in all_issues if checks.ERROR <= e.level < checks.CRITICAL and (not e.is_silenced())]
        criticals = [e for e in all_issues if checks.CRITICAL <= e.level and (not e.is_silenced())]
        sorted_issues = [(criticals, 'CRITICALS'), (errors, 'ERRORS'), (warnings, 'WARNINGS'), (infos, 'INFOS'), (debugs, 'DEBUGS')]
        for issues, group_name in sorted_issues:
            if issues:
                visible_issue_count += len(issues)
                formatted = (self.style.ERROR(str(e)) if e.is_serious() else self.style.WARNING(str(e)) for e in issues)
                formatted = '\n'.join(sorted(formatted))
                body += '\n%s:\n%s\n' % (group_name, formatted)
    if visible_issue_count:
        header = 'System check identified some issues:\n'
    if display_num_errors:
        if visible_issue_count:
            footer += '\n'
        footer += 'System check identified %s (%s silenced).' % ('no issues' if visible_issue_count == 0 else '1 issue' if visible_issue_count == 1 else '%s issues' % visible_issue_count, len(all_issues) - visible_issue_count)
    if any((e.is_serious(fail_level) and (not e.is_silenced()) for e in all_issues)):
        msg = self.style.ERROR('SystemCheckError: %s' % header) + body + footer
        raise SystemCheckError(msg)
    else:
        msg = header + body + footer
    if msg:
        if visible_issue_count:
            self.stderr.write(msg, lambda x: x)
        else:
            self.stdout.write(msg)

def valid_value(self, val):
    """Check to see if the provided value is a valid choice."""
    text_value = str(val)
    for k, v in self.choices:
        if isinstance(v, (list, tuple)):
            for k2, v2 in v:
                if val == k2 or text_value == str(k2):
                    return True
        elif val == k or text_value == str(k):
            return True
    return False

def to_python(self, value):
    """
        Validate that the input can be converted to a date. Return a Python
        datetime.date object.
        """
    if value in self.empty_values:
        return None
    if isinstance(value, datetime.datetime):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    return super().to_python(value)

