    return conditional_escape(value)

def _get_latest_lastmod(source, new_lastmod):
    """
    Returns the latest `lastmod` where `lastmod` can be either a date or a
    datetime.
    """
    if not isinstance(new_lastmod, datetime.datetime):
        new_lastmod = datetime.datetime.combine(new_lastmod, datetime.time.min)
    if timezone.is_naive(new_lastmod):
        new_lastmod = timezone.make_aware(new_lastmod, datetime.UTC)
    return new_lastmod if source is None else max(source, new_lastmod)

def urlsafe_base64_decode(entry):
    """
    Decode a base64 encoded string. Add back any trailing equal signs that
    might have been stripped.
    """
    entry = entry.encode()
    try:
        return base64.urlsafe_b64decode(entry.ljust(len(entry) + len(entry) % 4, b'='))
    except (LookupError, BinasciiError) as e:
        raise ValueError(e)

def save_form(self, request, form, change):
    """
        Given a ModelForm return an unsaved instance. ``change`` is True if
        the object is being changed, and False if it's being added.
        """
    return form.save(commit=False)

def _interpret_color(color: int | tuple[int, int, int] | str, offset: int=0) -> str:
    """Interprets a color value and returns the corresponding ANSI code."""
    if isinstance(color, str) and color in _ansi_colors:
        return str(_ansi_colors[color] + offset)
    elif isinstance(color, int) and (not isinstance(color, bool)):
        if 0 <= color <= 255:
            return f'{38 + offset};5;{color:d}'
    elif isinstance(color, (tuple, list)) and len(color) == 3 and all((isinstance(c, int) and (not isinstance(c, bool)) and (0 <= c <= 255) for c in color)):
        r, g, b = color
        return f'{38 + offset};2;{r:d};{g:d};{b:d}'
    raise ValueError(_('Unknown color {colour!r}').format(colour=color))

def can_fast_delete(self, objs, from_field=None):
    """
        Determine if the objects in the given queryset-like or single object
        can be fast-deleted. This can be done if there are no cascades, no
        parents and no signal listeners for the object class.

        The 'from_field' tells where we are coming from - we need this to
        determine if the objects are in fact to be deleted. Allow also
        skipping parent -> child -> parent chain preventing fast delete of
        the child.
        """
    if self.force_collection:
        return False
    if from_field and from_field.remote_field.on_delete is not CASCADE:
        return False
    if hasattr(objs, '_meta'):
        model = objs._meta.model
    elif hasattr(objs, 'model') and hasattr(objs, '_raw_delete'):
        model = objs.model
    else:
        return False
    if self._has_signal_listeners(model):
        return False
    opts = model._meta
    return all((link == from_field for link in opts.concrete_model._meta.parents.values())) and all((related.field.remote_field.on_delete in SKIP_COLLECTION for related in get_candidate_relations_to_delete(opts))) and (not any((hasattr(field, 'bulk_related_objects') for field in opts.private_fields)))

def get_object(self, queryset=None):
    """
        Return the object the view is displaying.

        Require `self.queryset` and a `pk` or `slug` argument in the URLconf.
        Subclasses can override this to return any object.
        """
    if queryset is None:
        queryset = self.get_queryset()
    pk = self.kwargs.get(self.pk_url_kwarg)
    slug = self.kwargs.get(self.slug_url_kwarg)
    if pk is not None:
        queryset = queryset.filter(pk=pk)
    if slug is not None and (pk is None or self.query_pk_and_slug):
        slug_field = self.get_slug_field()
        queryset = queryset.filter(**{slug_field: slug})
    if pk is None and slug is None:
        raise AttributeError('Generic detail view %s must be called with either an object pk or a slug in the URLconf.' % self.__class__.__name__)
    try:
        obj = queryset.get()
    except queryset.model.DoesNotExist:
        raise Http404(_('No %(verbose_name)s found matching the query') % {'verbose_name': queryset.model._meta.verbose_name})
    return obj

def get_initial_alias(self):
    """
        Return the first alias for this query, after increasing its reference
        count.
        """
    if self.alias_map:
        alias = self.base_table
        self.ref_alias(alias)
    elif self.model:
        alias = self.join(self.base_table_class(self.get_meta().db_table, None))
    else:
        alias = None
    return alias

def register(self, check=None, *tags, **kwargs):
    """
        Can be used as a function or a decorator. Register given function
        `f` labeled with given `tags`. The function should receive **kwargs
        and return list of Errors and Warnings.

        Example::

            registry = CheckRegistry()
            @registry.register('mytag', 'anothertag')
            def my_check(app_configs, **kwargs):
                # ... perform checks and collect `errors` ...
                return errors
            # or
            registry.register(my_check, 'mytag', 'anothertag')
        """

    def inner(check):
        if not func_accepts_kwargs(check):
            raise TypeError('Check functions must accept keyword arguments (**kwargs).')
        check.tags = tags
        checks = self.deployment_checks if kwargs.get('deploy') else self.registered_checks
        checks.add(check)
        return check
    if callable(check):
        return inner(check)
    else:
        if check:
            tags += (check,)
        return inner

def get_app_config(self, app_label):
    """
        Import applications and returns an app config for the given label.

        Raise LookupError if no application exists with this label.
        """
    self.check_apps_ready()
    try:
        return self.app_configs[app_label]
    except KeyError:
        message = "No installed app with label '%s'." % app_label
        for app_config in self.get_app_configs():
            if app_config.name == app_label:
                message += " Did you mean '%s'?" % app_config.label
                break
        raise LookupError(message)

def _column_generated_sql(self, field):
    """Return the SQL to use in a GENERATED ALWAYS clause."""
    expression_sql, params = field.generated_sql(self.connection)
    persistency_sql = self._column_generated_persistency_sql(field)
    if self.connection.features.requires_literal_defaults:
        expression_sql = expression_sql % tuple((self.quote_value(p) for p in params))
        params = ()
    return (f'GENERATED ALWAYS AS ({expression_sql}) {persistency_sql}', params)

