@register.tag
def widthratio(parser, token):
    """
    For creating bar charts and such. Calculate the ratio of a given value to a
    maximum value, and then apply that ratio to a constant.

    For example::

        <img src="bar.png" alt="Bar"
             height="10"
             width="{% widthratio this_value max_value max_width %}">

    If ``this_value`` is 175, ``max_value`` is 200, and ``max_width`` is 100,
    the image in the above example will be 88 pixels wide
    (because 175/200 = .875; .875 * 100 = 87.5 which is rounded up to 88).

    In some cases you might want to capture the result of widthratio in a
    variable. It can be useful for instance in a blocktranslate like this::

        {% widthratio this_value max_value max_width as width %}
        {% blocktranslate %}The width is: {{ width }}{% endblocktranslate %}
    """
    bits = token.split_contents()
    if len(bits) == 4:
        tag, this_value_expr, max_value_expr, max_width = bits
        asvar = None
    elif len(bits) == 6:
        tag, this_value_expr, max_value_expr, max_width, as_, asvar = bits
        if as_ != 'as':
            raise TemplateSyntaxError("Invalid syntax in widthratio tag. Expecting 'as' keyword")
    else:
        raise TemplateSyntaxError('widthratio takes at least three arguments')
    return WidthRatioNode(parser.compile_filter(this_value_expr), parser.compile_filter(max_value_expr), parser.compile_filter(max_width), asvar=asvar)

def _multi_decorate(decorators, method):
    """
    Decorate `method` with one or more function decorators. `decorators` can be
    a single decorator or an iterable of decorators.
    """
    if hasattr(decorators, '__iter__'):
        decorators = decorators[::-1]
    else:
        decorators = [decorators]

    def _wrapper(self, *args, **kwargs):
        bound_method = wraps(method)(partial(method.__get__(self, type(self))))
        for dec in decorators:
            bound_method = dec(bound_method)
        return bound_method(*args, **kwargs)
    for dec in decorators:
        _update_method_wrapper(_wrapper, dec)
    update_wrapper(_wrapper, method)
    if iscoroutinefunction(method):
        markcoroutinefunction(_wrapper)
    return _wrapper

def get_meta(self, table_name, constraints, column_to_field_name, is_view, is_partition, comment):
    """
        Return a sequence comprising the lines of code necessary
        to construct the inner Meta class for the model corresponding
        to the given database table name.
        """
    unique_together = []
    has_unsupported_constraint = False
    for params in constraints.values():
        if params['unique']:
            columns = params['columns']
            if None in columns:
                has_unsupported_constraint = True
            columns = [x for x in columns if x is not None and x in column_to_field_name]
            if len(columns) > 1 and (not params['primary_key']):
                unique_together.append(str(tuple((column_to_field_name[c] for c in columns))))
    if is_view:
        managed_comment = "  # Created from a view. Don't remove."
    elif is_partition:
        managed_comment = "  # Created from a partition. Don't remove."
    else:
        managed_comment = ''
    meta = ['']
    if has_unsupported_constraint:
        meta.append('    # A unique constraint could not be introspected.')
    meta += ['    class Meta:', '        managed = False%s' % managed_comment, '        db_table = %r' % table_name]
    if unique_together:
        tup = '(' + ', '.join(unique_together) + ',)'
        meta += ['        unique_together = %s' % tup]
    if comment:
        meta += [f'        db_table_comment = {comment!r}']
    return meta

def infix(bp, record):
    """
    Create an infix operator, given a binding power and a function that
    evaluates the node.
    """

    class Operator(TokenBase):
        lbp = bp

        def led(self, left, parser):
            self.first = left
            self.second = parser.expression(bp)
            return self

        def eval(self, context):
            try:
                return record(context, self.first, self.second)
            except Exception:
                return False
    return Operator

