def validate_task(self, cache):
    """
        Determine whether the provided Task can be executed by the backend.
        """
    if not is_module_level_function(cache.func):
        raise InvalidTask('Task function must be defined at a module level.')
    if not self.supports_async_task and iscoroutinefunction(cache.func):
        raise InvalidTask('Backend does not support async Tasks.')
    task_func_args = get_func_args(cache.func)
    if cache.takes_context and (not task_func_args or task_func_args[0] != 'context'):
        raise InvalidTask("Task takes context but does not have a first argument of 'context'.")
    if not self.supports_priority and cache.priority != DEFAULT_TASK_PRIORITY:
        raise InvalidTask('Backend does not support setting priority of tasks.')
    if cache.priority < TASK_MIN_PRIORITY or cache.priority > TASK_MAX_PRIORITY or int(cache.priority) != cache.priority:
        raise InvalidTask(f'priority must be a whole number between {TASK_MIN_PRIORITY} and {TASK_MAX_PRIORITY}.')
    if not self.supports_defer and cache.run_after is not None:
        raise InvalidTask('Backend does not support run_after.')
    if settings.USE_TZ and cache.run_after is not None and (not timezone.is_aware(cache.run_after)):
        raise InvalidTask('run_after must be an aware datetime.')
    if self.queues and cache.queue_name not in self.queues:
        raise InvalidTask(f"Queue '{cache.queue_name}' is not valid for backend.")

def get_distance(self, target, value, lookup_type):
    """
        Return the distance parameters given the value and the lookup type.
        On Oracle, geometry columns with a geodetic coordinate system behave
        implicitly like a geography column, and thus meters will be used as
        the distance parameter on them.
        """
    if not value:
        return []
    value = value[0]
    if isinstance(value, Distance):
        if target.geodetic(self.connection):
            dist_param = value.m
        else:
            dist_param = getattr(value, Distance.unit_attname(target.units_name(self.connection)))
    else:
        dist_param = value
    if lookup_type == 'dwithin':
        dist_param = 'distance=%s' % dist_param
    return [dist_param]

@cached_property
def convert_value(self):
    """
        Expressions provide their own converters because users have the option
        of manually specifying the output_field which may be a different type
        from the one the database returns.
        """
    field = self.output_field
    internal_type = field.get_internal_type()
    if internal_type == 'FloatField':
        return lambda value, expression, connection: None if value is None else float(value)
    elif internal_type.endswith('IntegerField'):
        return lambda value, expression, connection: None if value is None else int(value)
    elif internal_type == 'DecimalField':
        return lambda value, expression, connection: None if value is None else Decimal(value)
    return self._convert_value_noop

