def _add_class(classname: str, cls: Type[_T], token: _ClsRegistryType) -> None:
    """Add a class to the _decl_class_registry associated with the
    given declarative class.

    """
    if classname in token:
        existing = token[classname]
        if not isinstance(existing, _MultipleClassMarker):
            token[classname] = _MultipleClassMarker([cls, cast('Type[Any]', existing)])
    else:
        token[classname] = cls
    try:
        root_module = cast(_ModuleMarker, token['_sa_module_registry'])
    except KeyError:
        token['_sa_module_registry'] = root_module = _ModuleMarker('_sa_module_registry', None)
    tokens = cls.__module__.split('.')
    while tokens:
        token = tokens.pop(0)
        module = root_module.get_module(token)
        for token in tokens:
            module = module.get_module(token)
        try:
            module.add_class(classname, cls)
        except AttributeError as ae:
            if not isinstance(module, _ModuleMarker):
                raise exc.InvalidRequestError(f'name "{classname}" matches both a class name and a module name') from ae
            else:
                raise

