def get_param_argkeys(item: nodes.Item, scope: Scope) -> Iterator[ParamArgKey]:
    """Return all ParamArgKeys for item matching the specified high scope."""
    assert scope is not Scope.Function
    try:
        callspec: CallSpec2 = item.callspec
    except AttributeError:
        return
    item_cls = None
    if scope is Scope.Session:
        scoped_item_path = None
    elif scope is Scope.Package:
        scoped_item_path = item.path.parent
    elif scope is Scope.Module:
        scoped_item_path = item.path
    elif scope is Scope.Class:
        scoped_item_path = item.path
        item_cls = item.cls
    else:
        assert_never(scope)
    for argname in callspec.indices:
        if callspec._arg2scope[argname] != scope:
            continue
        param_index = callspec.indices[argname]
        yield ParamArgKey(argname, param_index, scoped_item_path, item_cls)

def cut(self, path: os.PathLike[str] | str | None=None, lineno: int | None=None, firstlineno: int | None=None, excludepath: os.PathLike[str] | None=None) -> Traceback:
    """Return a Traceback instance wrapping part of this Traceback.

        By providing any combination of path, lineno and firstlineno, the
        first frame to start the to-be-returned traceback is determined.

        This allows cutting the first part of a Traceback instance e.g.
        for formatting reasons (removing some uninteresting bits that deal
        with handling of the exception/traceback).
        """
    path_ = None if path is None else os.fspath(path)
    excludepath_ = None if excludepath is None else os.fspath(excludepath)
    for x in self:
        code = x.frame.code
        codepath = code.path
        if path is not None and str(codepath) != path_:
            continue
        if excludepath is not None and isinstance(codepath, Path) and (excludepath_ in (str(p) for p in codepath.parents)):
            continue
        if lineno is not None and x.lineno != lineno:
            continue
        if firstlineno is not None and x.frame.code.firstlineno != firstlineno:
            continue
        return Traceback(x._rawentry)
    return self

