def parse_known_and_unknown_args(self, args: Sequence[str | os.PathLike[str]], record: argparse.Namespace | None=None) -> tuple[argparse.Namespace, list[str]]:
    """Parse the known arguments at this point, and also return the
        remaining unknown flag arguments.

        :returns:
            A tuple containing an argparse namespace object for the known
            arguments, and a list of unknown flag arguments.
        """
    strargs = [os.fspath(x) for x in args]
    if sys.version_info < (3, 12, 8) or (3, 13) <= sys.version_info < (3, 13, 1):
        record, unknown = self.optparser.parse_known_args(strargs, record)
        assert record is not None
        file_or_dir = getattr(record, FILE_OR_DIR)
        unknown_flags: list[str] = []
        for arg in unknown:
            (unknown_flags if arg.startswith('-') else file_or_dir).append(arg)
        return (record, unknown_flags)
    else:
        return self.optparser.parse_known_intermixed_args(strargs, record)

