@contextlib.contextmanager
def _nested_result(self):
    """special API to support the use case of 'nested result sets'"""
    result_columns, ordered_columns = (self._result_columns, self._ordered_columns)
    self._result_columns, self._ordered_columns = ([], False)
    try:
        if self.stack:
            entry = self.stack[-1]
            entry['need_result_map_for_nested'] = True
        else:
            entry = None
        yield (self._result_columns, self._ordered_columns)
    finally:
        if entry:
            entry.pop('need_result_map_for_nested')
        self._result_columns, self._ordered_columns = (result_columns, ordered_columns)

