def assertrepr_compare(op: str, left: object, right: object, *, verbose: int, highlighter: _HighlightFunc, assertion_text_diff_style: _AssertionTextDiffStyle) -> Iterator[str]:
    """Yield specialised explanations for some operators/operands.

    The first line yielded is always the summary (``left op right``);
    subsequent lines are the detailed explanation. Yields nothing when no
    specialised explanation applies, which lets consumers map an empty
    iterator to "no explanation" without materialising anything.

    The iterator is lazy on purpose: a streaming consumer can stop pulling
    lines as soon as it has enough to show, so an enormous diff doesn't
    have to be built in full just to be thrown away.
    """
    use_ascii = isinstance(left, str) and isinstance(right, str) and (normalize('NFD', left) == normalize('NFD', right))
    if verbose > 1:
        left_repr = saferepr_unlimited(left, use_ascii=use_ascii)
        right_repr = saferepr_unlimited(right, use_ascii=use_ascii)
    else:
        maxsize = (80 - 15 - len(op) - 2) // 2
        left_repr = saferepr(left, maxsize=maxsize, use_ascii=use_ascii)
        right_repr = saferepr(right, maxsize=maxsize, use_ascii=use_ascii)
    summary = f'{left_repr} {op} {right_repr}'
    try:
        if op == '==':
            source = _compare_eq_any(left, right, highlighter, verbose, assertion_text_diff_style)
        elif op == 'not in' and istext(left) and istext(right):
            source = _notin_text(left, right, verbose)
        elif op in {'!=', '>=', '<=', '>', '<'} and isset(left) and isset(right):
            source = SET_COMPARISON_FUNCTIONS[op](left, right, highlighter, verbose)
        else:
            source = iter(())
        summary_yielded = False
        for line in source:
            if not summary_yielded:
                yield summary
                if line != '':
                    yield ''
                summary_yielded = True
            yield line
    except outcomes.Exit:
        raise
    except Exception:
        repr_crash = _pytest._code.ExceptionInfo.from_current()._getreprcrash()
        if not summary_yielded:
            yield summary
            yield ''
            summary_yielded = True
        yield f'(pytest_assertion plugin: representation of details failed: {repr_crash}.'
        yield ' Probably an object has a faulty __repr__.)'

def polymorphic_union(table_map, typecolname, aliasname='p_union', cast_nulls=True):
    """Create a ``UNION`` statement used by a polymorphic mapper.

    See  :ref:`concrete_inheritance` for an example of how
    this is used.

    :param table_map: mapping of polymorphic identities to
     :class:`_schema.Table` objects.
    :param typecolname: string name of a "discriminator" column, which will be
     derived from the query, producing the polymorphic identity for
     each row.  If ``None``, no polymorphic discriminator is generated.
    :param aliasname: name of the :func:`~sqlalchemy.sql.expression.alias()`
     construct generated.
    :param cast_nulls: if True, non-existent columns, which are represented
     as labeled NULLs, will be passed into CAST.   This is a legacy behavior
     that is problematic on some backends such as Oracle - in which case it
     can be set to False.

    """
    colnames: util.OrderedSet[str] = util.OrderedSet()
    colnamemaps = {}
    types = {}
    for key in table_map:
        table = table_map[key]
        table = coercions.expect(roles.FromClauseRole, table)
        table_map[key] = table
        m = {}
        for c in table.c:
            if c.key == typecolname:
                raise sa_exc.InvalidRequestError("Polymorphic union can't use '%s' as the discriminator column due to mapped column %r; please apply the 'typecolname' argument; this is available on ConcreteBase as '_concrete_discriminator_name'" % (typecolname, c))
            colnames.add(c.key)
            m[c.key] = c
            types[c.key] = c.type
        colnamemaps[table] = m

    def col(name, table):
        try:
            return colnamemaps[table][name]
        except KeyError:
            if cast_nulls:
                return sql.cast(sql.null(), types[name]).label(name)
            else:
                return sql.type_coerce(sql.null(), types[name]).label(name)
    result = []
    for type_, table in table_map.items():
        if typecolname is not None:
            result.append(sql.select(*[col(name, table) for name in colnames] + [sql.literal_column(sql_util._quote_ddl_expr(type_)).label(typecolname)]).select_from(table))
        else:
            result.append(sql.select(*[col(name, table) for name in colnames]).select_from(table))
    return sql.union_all(*result).alias(aliasname)

@classmethod
def _create_description_match_map(cls, item: Sequence[ResultColumnsEntry], loose_column_name_matching: bool=False) -> Dict[Union[str, object], Tuple[str, TupleAny, TypeEngine[Any], int]]:
    """when matching cursor.description to a set of names that are present
        in a Compiled object, as is the case with TextualSelect, get all the
        names we expect might match those in cursor.description.
        """
    d: Dict[Union[str, object], Tuple[str, TupleAny, TypeEngine[Any], int]] = {}
    for ridx, elem in enumerate(item):
        key = elem[RM_RENDERED_NAME]
        if key in d:
            e_name, e_obj, e_type, e_ridx = d[key]
            d[key] = (e_name, e_obj + elem[RM_OBJECTS], e_type, ridx)
        else:
            d[key] = (elem[RM_NAME], elem[RM_OBJECTS], elem[RM_TYPE], ridx)
        if loose_column_name_matching:
            for r_key in elem[RM_OBJECTS]:
                d.setdefault(r_key, (elem[RM_NAME], elem[RM_OBJECTS], elem[RM_TYPE], ridx))
    return d

