def _infer_parametrize_scope(argnames: Sequence[str], arg2fixturedefs: Mapping[str, Sequence[fixtures.FixtureDef[object]]], indirect: bool | Sequence[str]) -> Scope:
    """Infer the most appropriate scope for a parametrize() call based on its
    arguments, for when the scope is not explicitly specified.

    When there's at least one direct argument, always use "function" scope.

    When a test function is parametrized and all its arguments are indirect
    (e.g. fixtures), return the most narrow scope based on the fixtures used.

    Related to issue #1832, based on code posted by @Kingdread.
    """
    if isinstance(indirect, Sequence):
        all_arguments_are_fixtures = len(indirect) == len(argnames)
    else:
        all_arguments_are_fixtures = bool(indirect)
    if all_arguments_are_fixtures:
        used_scopes = (arg2fixturedefs[argname][-1]._scope for argname in argnames if argname in arg2fixturedefs)
        return min(used_scopes, default=Scope.Function)
    return Scope.Function

